contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 shareAmount, uint256 deadline) public {
        require(shareAmount > c.balanceOf(address(this)), "must exceed balance");
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        bytes memory data = new bytes(0);
        c.sellShares(shareAmount, address(this), 0, 0, data, deadline); if (__ESBMC_reverted()) return;
        reverted = false;

        assert(reverted && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balBefore);
    }

    receive() external payable {}
}

