        c = new GSPFunding();
    }

    function _run(uint256 shareAmount, uint256 deadline) internal {
        vm.assume(shareAmount > c.balanceOf(address(this)));
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        bytes memory data = new bytes(0);
        try c.sellShares(shareAmount, address(this), 0, 0, data, deadline) {} catch { return; }
        reverted = false;
        assertTrue(reverted && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balBefore);
